
const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',...opt,headers:{'content-type':'application/json',...(opt.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(d.error||`Request failed (${r.status})`),{data:d,status:r.status});return d}
function iconSvg(name){const p={search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',home:'<path d="m3 10 9-7 9 7"/><path d="M5 9v11h14V9"/><path d="M9 20v-6h6v6"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-3 6-5 2 2-5 6-3Z"/>',library:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',pen:'<path d="m15 5 4 4"/><path d="M4 20h4L19 9a2.8 2.8 0 0 0-4-4L4 16v4Z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/>',user:'<circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 0 0-16 0"/>',trending:'<path d="m3 17 6-6 4 4 8-9"/><path d="M15 6h6v6"/>',genres:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',rank:'<path d="M8 21h8M12 17v4"/><path d="M7 4h10l-1 8a4 4 0 0 1-8 0L7 4Z"/><path d="M7 6H4v2a4 4 0 0 0 4 4M17 6h3v2a4 4 0 0 1-4 4"/>',crown:'<path d="m2 8 5 4 5-8 5 8 5-4-2 12H4L2 8Z"/><path d="M4 16h16"/>',sparkles:'<path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-1.9-5.8L4 11l6.1-2.2L12 3Z"/><path d="m19 14 1.2 2.8L23 18l-2.8 1.2L19 22l-1.2-2.8L15 18l2.8-1.2L19 14Z"/>'};return '<svg class="imperialIcon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(p[name]||p.sparkles)+'</svg>'}
function img(url,title=''){
  const t=String(title||'').toLowerCase();
  const fallback=[
    [/imperial ascendant|ascendant/,'/covers/ascendant.jpg'],
    [/glass throne|glass/,'/covers/glass.jpg'],
    [/system named mercy|mercy/,'/covers/mercy.jpg'],
    [/neon archive|neon/,'/covers/neon.jpg'],
    [/crown of ember|ember/,'/covers/ember.jpg'],
    [/rain of swords|swords/,'/covers/swords.jpg'],
    [/silent isekai|isekai/,'/covers/isekai.jpg'],
    [/last cartographer|cartographer/,'/covers/cartographer.jpg']
  ];
  // Prefer bundled title-matched covers for the known launch catalog.
  // For other novels, preserve the publisher/admin supplied cover URL.
  for(const [pattern,path] of fallback){if(pattern.test(t))return path}
  return url?esc(url):'/story-cover-placeholder.svg'
}
function card(n){return `<a class="card" href="/novel/${n.id}"><div class="cover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)} cover" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/story-cover-placeholder.svg'"></div><div class="cardBody"><div class="cardTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown author')}</div><div class="meta"><span>★ ${Number(n.rating||0).toFixed(1)}</span><span>◷ ${Number(n.chapter_count||n.latest_chapter||0)} ch.</span></div></div></a>`}
function chapterRow(ch,id){return `<a class="chapter" href="/read/${id}/${ch.chapter_number}"><span class="chapterNo">${ch.chapter_number}</span><span><b>${esc(ch.title)}</b><br><span class="muted">${ch.is_locked?'Locked · '+ch.ticket_cost+' Imperial Crowns':'Free to read'}</span></span><span class="lock">${ch.is_locked?'⌑':'›'}</span></a>`}
const COMIC_FORMATS=new Set(['manga','manhwa','manhua','webtoon','comic','graphic_novel']);
function renderChapterContent(raw,kind){
 const fallback=esc(raw||'This chapter has no content yet.');
 if(!COMIC_FORMATS.has(String(kind||'').toLowerCase()))return fallback;
 let payload;try{payload=JSON.parse(String(raw||''))}catch{return fallback}
 if(payload?.type!=='imperial_comic_chapter'||payload.version!==1||!Array.isArray(payload.pages)||!payload.pages.length)return fallback;
 const pages=payload.pages.slice(0,300).map((page,i)=>{
  const src=String(page?.src||'').trim();
  const safeSrc=(src.startsWith('/')&&!src.startsWith('//')&&!src.includes('\\'))||/^https:\/\/[^\s"'<>]+$/i.test(src);
  const alt=esc(String(page?.alt||('Comic page '+(i+1))).slice(0,300));
  const caption=String(page?.caption||'').slice(0,500);
  if(!safeSrc)return '<div class="comicPageUnavailable" role="note">This page image has an invalid or unsupported address.</div>';
  return '<figure class="comicPage" data-comic-page="'+i+'"><img src="'+esc(src)+'" alt="'+alt+'" loading="'+(i===0?'eager':'lazy')+'" decoding="async"'+(i===0?' fetchpriority="high"':'')+'>'+(caption?'<figcaption>'+esc(caption)+'</figcaption>':'')+'</figure>';
 }).join('');
 return '<section class="comicReader" id="comicReader" aria-label="Comic chapter reader"><div class="comicReaderControls"><button type="button" id="comicModeToggle" class="secondary">Switch to single-page mode</button><div class="comicPageNav"><button type="button" id="comicPrev" class="readerTool" aria-label="Previous comic page" disabled>←</button><span id="comicPageStatus" aria-live="polite">Vertical scroll · '+pages.length+' pages</span><button type="button" id="comicNext" class="readerTool" aria-label="Next comic page" disabled>→</button></div></div><div class="comicPages" id="comicPages">'+pages+'</div></section>';
}
function initComicViewer(){
 const viewer=$('#comicReader');if(!viewer)return;
 const pages=$('.comicPage',viewer),toggle=$('#comicModeToggle'),prev=$('#comicPrev'),next=$('#comicNext'),status=$('#comicPageStatus');
 let single=false,current=0;
 pages.forEach(page=>{const image=$('img',page);if(image)image.addEventListener('error',()=>page.classList.add('comicPageError'),{once:true})});
 const paint=()=>{viewer.classList.toggle('is-single',single);pages.forEach((page,i)=>{page.classList.toggle('is-current',i===current);page.setAttribute('aria-hidden',String(single&&i!==current));});toggle.textContent=single?'Switch to vertical-scroll mode':'Switch to single-page mode';prev.disabled=!single||current===0;next.disabled=!single||current===pages.length-1;status.textContent=single?'Page '+(current+1)+' of '+pages.length:'Vertical scroll · '+pages.length+' pages';};
 toggle.addEventListener('click',()=>{single=!single;paint()});prev.addEventListener('click',()=>{current=Math.max(0,current-1);paint()});next.addEventListener('click',()=>{current=Math.min(pages.length-1,current+1);paint()});paint();
}
function formatKindLabel(kind){return ({original:'Original novel',fanfiction:'Fanfiction',light_novel:'Light novel',web_novel:'Web novel',manga:'Manga',manhwa:'Manhwa',manhua:'Manhua',webtoon:'Webtoon',comic:'Comic',graphic_novel:'Graphic novel',anime:'Anime listing',cartoon:'Cartoon listing',audiobook:'Audiobook listing',drama:'Drama adaptation listing',game:'Game listing'})[String(kind||'original').toLowerCase()]||'Story';}
function catalogCard(n){const genres=(n.genres||[]).slice(0,2).map(g=>`<span class="pill">${esc(typeof g==='string'?g:g.name)}</span>`).join('');const tags=(n.tags||[]).slice(0,2).map(t=>`<span class="pill purple">#${esc(typeof t==='string'?t:t.name)}</span>`).join('');const status=String(n.status||'ongoing');return `<a class="catalogCard" href="/novel/${n.id}"><div class="catalogCover"><img src="${img(n.cover_url,n.title)}" alt="${esc(n.title)} cover" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/story-cover-placeholder.svg'"><span class="statusBadge">${esc(status)}</span><span class="formatBadge">${esc(formatKindLabel(n.kind))}</span></div><div class="catalogBody"><div class="catalogTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown author')}</div><div class="catalogStats"><span>★ ${Number(n.rating||0).toFixed(1)}</span><span>◷ ${Number(n.chapter_count||n.latest_chapter||0)} ch.</span><span>◉ ${Number(n.views||0).toLocaleString()}</span></div><div class="catalogTags">${genres}${tags}</div><span class="readMini">${['anime','cartoon','audiobook','drama','game'].includes(String(n.kind||'').toLowerCase())?'View Details →':'Read Story →'}</span></div></a>`}
function applyImperialTheme(theme){const chosen=theme==='light'?'light':'dark';document.documentElement.dataset.theme=chosen;try{localStorage.setItem('imperial_theme',chosen)}catch(e){}const btn=document.querySelector('[data-theme-toggle]');if(btn){btn.setAttribute('aria-label',chosen==='dark'?'Switch to light mode':'Switch to dark mode');btn.setAttribute('title',chosen==='dark'?'Switch to light mode':'Switch to dark mode');btn.innerHTML=chosen==='dark'?'☼':'☾'}return chosen}
function initImperialTheme(){let chosen='light';try{chosen=localStorage.getItem('imperial_theme')||'light'}catch(e){}document.documentElement.dataset.theme=chosen==='dark'?'dark':'light'}
initImperialTheme();
