 const filterNames={q:'Search',sort:'Sort',status:'Status',genre:'Genre',tag:'Tag',kind:'Type',language:'Language',min_rating:'Rating'};
 const friendly={sort:{updated:'Recently updated',newest:'Newest',trending:'Trending',views:'Most viewed',rating:'Top rated',chapters:'Most chapters'},status:{ongoing:'Ongoing',completed:'Completed'},kind:{original:'Original novels',fanfiction:'Fanfiction',manga:'Manga',manhwa:'Manhwa',manhua:'Manhua',webtoon:'Webtoons',comic:'Comics',graphic_novel:'Graphic novels',light_novel:'Light novels',web_novel:'Web novels',anime:'Anime',cartoon:'Cartoons'}};
 const filterHref=except=>{const p=new URLSearchParams();for(const [k,v] of Object.entries(vals))if(v&&k!==except&&!(k==='sort'&&v==='updated'))p.set(k,v);return '/catalog'+(p.toString()?'?'+p.toString():'')};
 const renderFilterChips=()=>{const active=Object.entries(vals).filter(([k,v])=>v&&!(k==='sort'&&v==='updated'));const el=$('#activeFilters');if(!active.length){el.innerHTML='';el.hidden=true;return}el.hidden=false;el.innerHTML='<span class="activeFiltersLabel">Active filters</span>'+active.map(([k,v])=>{const label=friendly[k]?.[v]||v;return '<a class="activeFilter" href="'+esc(filterHref(k))+'" aria-label="Remove '+esc(filterNames[k]||k)+' filter"><span>'+esc(filterNames[k]||k)+': '+esc(label)+'</span><b aria-hidden="true">×</b></a>'}).join('')+'<a class="clearFilters" href="/catalog">Clear all</a>'};
