  async function load(period){const d=await api('/api/leaderboard?period='+period);$('#lbNovels').innerHTML=(d.novels||[]).map((n,i)=>`<article class="panel"><div class="rankBadge">#${i+1}</div><div class="cardTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||'Unknown')}</div><div class="meta"><span>★ ${Number(n.rating||0).toFixed(1)}</span><span>◉ ${Number(n.views||0).toLocaleString()} views</span><span>◷ ${Number(n.chapter_count||0)} ch.</span></div><a class="ghost" href="/novel/${n.id}">Open Novel →</a></article>`).join('')||'<div class="empty">No ranked novels yet.</div>';$('#lbAuthors').innerHTML=(d.authors||[]).map((x,i)=>`<article class="panel"><div class="rankBadge">#${i+1}</div><h3>${esc(x.author)}</h3><div class="meta"><span>${Number(x.novels||0)} novels</span><span>★ ${Number(x.rating||0).toFixed(1)}</span><span>◉ ${Number(x.views||0).toLocaleString()} views</span></div><a class="ghost" href="/catalog?author=${encodeURIComponent(x.author)}">View stories →</a></article>`).join('')||'<div class="empty">No ranked authors yet.</div>'}
  $$('.period').forEach(b=>b.onclick=()=>{$$('.period').forEach(x=>x.classList.remove('active'));b.classList.add('active');load(b.dataset.period)});load('weekly');return;
